# 02_harness.R
# Expanding-window forecast experiment (project guide Stage 2, Step 2).
# Owner: Dawson. Model owners do not edit this file; they write model functions
# that follow the interface below and add them to the model list in stage2.qmd.
#
# ---------------------------------------------------------------------------
# MODEL INTERFACE
#   model_fn(train) -> tibble(h, forecast)
#
#   train : tibble of every quarter from 1960Q1 through the forecast origin T,
#           sorted by qtr, no gaps. Columns: qtr, infl, unrate, tbill.
#           The last row is the origin T.
#   return: point forecasts of inflation for T+h. Must include h = 1, 4, 8.
#           Iterated models can return h = 1:8; direct models can return only
#           the three horizons they estimate. Extra horizons are ignored.
#
#   Rules:
#   - Use ONLY `train`. Never reference the full dataset or any global object
#     built from it (that would leak data after T into the forecast).
#   - Construct one-sided variables (local mean, gap, lags) inside the function,
#     from `train`.
#   - Lag selection (BIC) also happens inside the function, at every origin.
#   - Estimated models (3, 4, 5, 7) also export fit_<name>(train) for Step 5,
#     which refits the best h = 1 model through 2019Q4. It returns
#       list(fit = <lm>, p = <chosen lag>, resid = tibble(qtr, resid))
#     where resid holds the in-sample residuals dated by quarter.
#     Direct models: fit_<name>(train, h = 1) returns the h = 1 equation.
# ---------------------------------------------------------------------------

HORIZONS     <- c(1, 4, 8)
FIRST_ORIGIN <- "1999 Q4"
LAST_TARGET  <- "2019 Q4"

# check one model's output at one origin
check_forecast <- function(fc, model, origin) {
  where <- paste0("model '", model, "' at origin ", format(origin))
  if (!is.data.frame(fc) || !all(c("h", "forecast") %in% names(fc)))
    stop(where, ": must return a tibble with columns h and forecast")
  if (!all(HORIZONS %in% fc$h) || anyDuplicated(fc$h))
    stop(where, ": must return one forecast for each of h = ", paste(HORIZONS, collapse = ", "))
  if (any(!is.finite(fc$forecast[fc$h %in% HORIZONS])))
    stop(where, ": returned a missing or infinite forecast")
  invisible(TRUE)
}

# run every model at every origin and save h = 1, 4, 8 forecasts with their errors
run_harness <- function(data, models,
                        horizons = HORIZONS,
                        first_origin = FIRST_ORIGIN,
                        last_target = LAST_TARGET) {
  stopifnot(is.list(models), !is.null(names(models)), all(names(models) != ""))
  d <- as_tibble(data) |> arrange(qtr) |> select(qtr, infl, unrate, tbill)

  first_i <- which(d$qtr == yearquarter(first_origin))
  last_i  <- which(d$qtr == yearquarter(last_target))
  stopifnot(length(first_i) == 1, length(last_i) == 1)
  origins <- first_i:(last_i - min(horizons))      # 1999Q4 through 2019Q3

  out <- vector("list", length(origins) * length(models))
  k <- 0
  for (i in origins) {
    train <- d[seq_len(i), ]                        # data through origin T only
    for (m in names(models)) {
      fc <- models[[m]](train)
      check_forecast(fc, m, d$qtr[i])
      fc <- fc[fc$h %in% horizons & i + fc$h <= last_i, ]   # keep targets <= 2019Q4
      k <- k + 1
      out[[k]] <- tibble(
        origin   = d$qtr[i],
        target   = d$qtr[i + fc$h],
        h        = as.integer(fc$h),
        model    = m,
        forecast = fc$forecast,
        actual   = d$infl[i + fc$h],                # attached after the forecast is saved
        error    = actual - forecast)               # e = realized - forecast
    }
  }
  bind_rows(out)
}

# expected error counts from the project guide: 80 / 77 / 73
check_error_counts <- function(results) {
  expected <- tibble(h = c(1L, 4L, 8L), n_expected = c(80L, 77L, 73L),
                     first_target = c("2000 Q1", "2000 Q4", "2001 Q4"))
  got <- results |>
    group_by(model, h) |>
    summarize(n = n(), first_target = format(min(target)),
              last_target = format(max(target)), .groups = "drop") |>
    left_join(expected, by = "h", suffix = c("", "_expected"))
  ok <- with(got, n == n_expected & first_target == first_target_expected &
                  last_target == LAST_TARGET)
  if (!all(ok)) {
    print(got[!ok, ])
    stop("Error counts or target ranges do not match the project guide")
  }
  got |> select(model, h, n, first_target, last_target)
}

# keep only models whose functions run; lets the report render while some are TODO
available_models <- function(models, data) {
  d <- as_tibble(data) |> arrange(qtr) |> select(qtr, infl, unrate, tbill)
  train <- d[seq_len(which(d$qtr == yearquarter(FIRST_ORIGIN))), ]
  ok <- vapply(names(models), function(m) {
    tryCatch({ check_forecast(models[[m]](train), m, tail(train$qtr, 1)); TRUE },
             error = function(e) FALSE)
  }, logical(1))
  if (any(!ok)) message("Not yet implemented or failing: ", paste(names(models)[!ok], collapse = ", "))
  models[ok]
}
